package org.usbworkbench;
import java.io.*;import java.nio.file.*;import java.nio.charset.*;import java.util.*;
public class OpticalImageTest {
 static int checks;static void check(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}interface A{void run()throws Exception;}static void fails(String code,A a)throws Exception{try{a.run();throw new AssertionError("expected "+code);}catch(IOException e){check(e.getMessage().startsWith(code),e.toString());}}
 static class Memory implements OpticalImage.Source {final byte[] data;long length;Memory(byte[] b){data=b;length=b.length;}public long size(){return length;}public void read(long at,byte[] b,int off,int n)throws IOException{if(at<0||n<0||at>length||n>length-at)throw new IOException("BOUNDS");Arrays.fill(b,off,off+n,(byte)0);if(at<data.length){int count=(int)Math.min(n,data.length-at);System.arraycopy(data,(int)at,b,off,count);}}public void close(){}}
 static class Sink implements OpticalImage.Sink {final Map<String,ByteArrayOutputStream> files=new HashMap<>();final Set<String> dirs=new HashSet<>();boolean corrupt;public void directory(String path){dirs.add(path);}public OutputStream file(String path){ByteArrayOutputStream out=new ByteArrayOutputStream();files.put(path,out);return out;}public InputStream reopen(String path){byte[] b=files.get(path).toByteArray();if(corrupt&&b.length>0)b[0]^=1;return new ByteArrayInputStream(b);}}
 static DiskTools.Progress p=(a,b)->{};
 static void both32(byte[] b,int at,long n){DiskTools.le32(b,at,n);for(int i=0;i<4;i++)b[at+4+i]=(byte)(n>>>(24-8*i));}
 public static void main(String[] args)throws Exception{
  for(String name:new String[]{"plain","joliet","udf"}){byte[] bytes=Files.readAllBytes(Paths.get("artifacts/optical-fixtures/"+name+".iso"));Memory source=new Memory(bytes);OpticalImage.Manifest manifest=OpticalImage.scan(source,p);check(manifest.entries.size()==9,name+" entry count "+manifest.entries.size());check(manifest.windowsPreflight(source).equals("x64"),name+" Windows layout");OpticalImage.Entry text=manifest.find(name.equals("plain")?"ARABIC.TXT":"ملف.txt");check(text!=null,"Unicode entry "+name);byte[] data=new byte[(int)text.size];OpticalImage.read(source,text,0,data,0,data.length);check(new String(data,StandardCharsets.UTF_8).equals("مرحبا USB"),"Unicode payload "+name);Sink sink=new Sink();OpticalImage.extract(source,manifest,sink,p);check(sink.files.size()==6&&sink.dirs.size()==3,"extracted tree "+name);check(sink.files.containsKey(name.equals("plain")?"EMPTY":"empty"),"empty file "+name);Sink bad=new Sink();bad.corrupt=true;fails("VERIFY_FAILED",()->OpticalImage.extract(source,manifest,bad,p));System.out.println("PASS independent "+name+" fixture: "+manifest.filesystem);}
  byte[] iso=Files.readAllBytes(Paths.get("artifacts/optical-fixtures/plain.iso"));Memory original=new Memory(iso);OpticalImage.Manifest parsed=OpticalImage.scan(original,p);OpticalImage.Entry install=parsed.find("sources/install.esd");OpticalImage.Manifest large=new OpticalImage.Manifest("fixture");for(OpticalImage.Entry entry:parsed.entries){if(entry==install)large.add(new OpticalImage.Entry("sources/install.wim",false,0x100000001L,Arrays.asList(entry.ranges.get(0),new OpticalImage.Range(-1,0x100000001L-entry.size))));else large.add(entry);}fails("WIM_SPLIT_REQUIRED",()->large.windowsPreflight(original));check(large.windowsPreflight(original,true).equals("x64"),"large WIM accepted only with tested split engine flag");
  OpticalImage.Manifest invalidName=new OpticalImage.Manifest("fixture");for(OpticalImage.Entry e:parsed.entries)invalidName.add(e);invalidName.add(new OpticalImage.Entry("sources/CON.txt",false,0,Collections.emptyList()));fails("WINDOWS_FILE_NAME",()->invalidName.windowsPreflight(original,true));
  byte[] multi=iso.clone();OpticalImage.Entry sources=parsed.find("sources");int begin=(int)sources.ranges.get(0).offset,end=begin+(int)sources.size;boolean patched=false;for(int at=begin;at<end;){int length=multi[at]&255;if(length==0)break;String name=new String(multi,at+33,multi[at+32]&255,"US-ASCII");if(name.startsWith("INSTALL.ESD")){byte[] second=Arrays.copyOfRange(multi,at,at+length);System.arraycopy(multi,at+length,multi,at+2*length,end-at-2*length);multi[at+25]|=(byte)128;both32(multi,at+10,0xfffff800L);both32(second,2,5000000);both32(second,10,4096);System.arraycopy(second,0,multi,at+length,length);patched=true;break;}at+=length;}check(patched,"multi-extent fixture created");both32(multi,16*2048+80,6000000);Memory sparse=new Memory(multi);sparse.length=6000000L*2048;OpticalImage.Entry joined=OpticalImage.scan(sparse,p).find("sources/install.esd");check(joined.ranges.size()==2&&joined.size==0x100000800L,"ISO level3 extent sizes above4GiB preserved");byte[] boundary=new byte[6];OpticalImage.read(sparse,joined,0xfffff800L-3,boundary,0,6);check(Arrays.equals(boundary,new byte[6]),"read across multi-extent boundary without full-image allocation");
  iso[16*2048+84]^=1;fails("ISO_ENDIAN",()->OpticalImage.scan(new Memory(iso),p));
  byte[] udf=Files.readAllBytes(Paths.get("artifacts/optical-fixtures/udf.iso"));udf[256*2048+4]^=1;udf[udf.length-2048+4]^=1;int back=udf.length-257*2048+4;if(back>0)udf[back]^=1;fails("UDF_UNSUPPORTED_OR_DAMAGED",()->OpticalImage.scan(new Memory(udf),p));
  System.out.println("PASS: "+checks+" independent ISO9660/Joliet/UDF parsing, extraction, Unicode, Windows layout and corruption checks");
 }
}
